CustomField.formula:
IF(NOT(ISBLANK(BillingState)),
    IF(CONTAINS($Label.Subregion_AMER_Pacific_Northwest,BillingState + ";"),"AMER - Pacific Northwest",
        IF(BillingState = "California" || BillingState = "CA","AMER - California",
            IF(CONTAINS($Label.Subregion_AMER_Mountain_West,BillingState + ";"),"AMER - Mountain West",
                IF(CONTAINS($Label.Subregion_AMER_Southwest,BillingState + ";"),"AMER - Southwest",
                    IF(CONTAINS($Label.Subregion_AMER_Midwest,BillingState + ";"),"AMER - Midwest",
                        IF(CONTAINS($Label.Subregion_AMER_Southeast,BillingState + ";"),"AMER - Southeast",
                            IF(CONTAINS($Label.Subregion_AMER_Mid_Atlantic,BillingState + ";"),"AMER - Mid Atlantic",
                                IF(CONTAINS($Label.Subregion_AMER_Northeast,BillingState + ";"),"AMER - Northeast",
                                    CASE(BillingState,
                                    "NY","AMER - New York",
                                    "New York","AMER - New York",
                                    "NJ","AMER - Northeast",
                                    "New Jersey","AMER - Northeast",
                                    "PA","AMER - New York",
                                    "Pennsylvania","AMER - Northeast",
                                    "Puerto Rico","AMER - N/A",
                                    "")
                                )
                            )
                        )
                    )
                )
            )
        )
    ),
    ""
)
